export function createTreeTable(root){
  const buttons=[...root.querySelectorAll('[data-folder]')];
  const onClick=event=>{const button=event.target.closest('[data-folder]');if(!button||!root.contains(button))return;const key=button.dataset.folder;const open=button.getAttribute('aria-expanded')!=='true';button.setAttribute('aria-expanded',String(open));button.textContent=open?'▾':'▸';button.setAttribute('aria-label',`${open?'Collapse':'Expand'} ${button.parentElement.textContent.replace(/[▾▸]/g,'').trim()}`);root.querySelectorAll(`[data-parent="${key}"]`).forEach(row=>row.hidden=!open);};
  root.addEventListener('click',onClick);return{destroy(){root.removeEventListener('click',onClick)}};
