export function createCommandMenu(root) {
  const dialog = root.querySelector('[data-command-dialog]');
  const openButton = root.querySelector('[data-command-open]');
  const input = root.querySelector('[data-command-search]');
  const options = [...root.querySelectorAll('[role="option"]')];
  const empty = root.querySelector('[data-command-empty]');
  const result = root.querySelector('[data-command-result]');
  if (!(dialog instanceof HTMLDialogElement) || !(openButton instanceof HTMLButtonElement) || !(input instanceof HTMLInputElement)) throw new Error('Command menu markup is incomplete.');
  let activeIndex = -1;
  let returnFocus = null;
  const visibleOptions = () => options.filter(option => !option.hidden);
  const setActive = index => {
    const visible = visibleOptions();
    if (!visible.length) { activeIndex = -1; input.removeAttribute('aria-activedescendant'); return; }
    activeIndex = (index + visible.length) % visible.length;
    visible.forEach((option, i) => option.setAttribute('aria-selected', String(i === activeIndex)));
    const active = visible[activeIndex];
    active.id ||= `command-option-${activeIndex}`;
    input.setAttribute('aria-activedescendant', active.id);
    active.scrollIntoView({ block: 'nearest' });
  };
  const filter = () => {
    const query = input.value.trim().toLocaleLowerCase();
    options.forEach(option => { option.hidden = !`${option.dataset.command} ${option.dataset.keywords} ${option.textContent}`.toLocaleLowerCase().includes(query); });
    const visible = visibleOptions();
    empty.hidden = visible.length !== 0;
    setActive(visible.length ? 0 : -1);
  };
  const close = () => { if (dialog.open) dialog.close(); };
  const open = () => {
    returnFocus = document.activeElement instanceof HTMLElement ? document.activeElement : openButton;
    input.value = '';
    filter();
    dialog.showModal();
    input.focus();
  };
  const run = option => {
    if (!option) return;
    result.textContent = `Command selected: ${option.dataset.command}.`;
    close();
  };
  const onKeydown = event => {
    const visible = visibleOptions();
    if (event.key === 'ArrowDown') { event.preventDefault(); setActive(activeIndex + 1); }
    else if (event.key === 'ArrowUp') { event.preventDefault(); setActive(activeIndex - 1); }
    else if (event.key === 'Enter') { event.preventDefault(); run(visible[activeIndex]); }
  };
  const onGlobalKeydown = event => {
    if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); dialog.open ? close() : open(); }
  };
  openButton.addEventListener('click', open);
  input.addEventListener('input', filter);
  input.addEventListener('keydown', onKeydown);
  options.forEach(option => option.addEventListener('click', () => run(option)));
  dialog.addEventListener('close', () => returnFocus?.focus());
  document.addEventListener('keydown', onGlobalKeydown);
  return { destroy() { openButton.removeEventListener('click', open); input.removeEventListener('input', filter); input.removeEventListener('keydown', onKeydown); document.removeEventListener('keydown', onGlobalKeydown); } };
}
