export function createContextMenu(root) {
  const target = root.querySelector('[data-context-target]');
  const visibleTrigger = root.querySelector('[data-context-visible-trigger]');
  const menu = root.querySelector('[role="menu"]');
  const items = [...root.querySelectorAll('[role="menuitem"]')];
  const feedback = root.querySelector('[data-context-feedback]');
  if (!(target instanceof HTMLElement) || !(visibleTrigger instanceof HTMLButtonElement) || !(menu instanceof HTMLElement)) throw new Error('Context menu markup is incomplete.');
  let returnFocus = false;
  const enabledItems = () => items.filter(item => item.getAttribute('aria-disabled') !== 'true');
  const close = (restore = false) => { menu.hidden = true; target.setAttribute('aria-expanded', 'false'); if (restore && returnFocus) target.focus(); };
  const openAt = (x, y, keyboard = false) => {
    const bounds = root.getBoundingClientRect();
    returnFocus = keyboard;
    menu.hidden = false;
    target.setAttribute('aria-expanded', 'true');
    const menuRect = menu.getBoundingClientRect();
    const left = Math.max(8, Math.min(x - bounds.left, bounds.width - menuRect.width - 8));
    const top = Math.max(8, Math.min(y - bounds.top, bounds.height - menuRect.height - 8));
    menu.style.left = `${left}px`;
    menu.style.top = `${top}px`;
    enabledItems()[0]?.focus();
  };
  const onContext = event => { event.preventDefault(); openAt(event.clientX, event.clientY); };
  const onVisibleOpen = () => { const rect = visibleTrigger.getBoundingClientRect(); openAt(rect.left + rect.width / 2, rect.top + rect.height / 2, true); };
  const onTargetKey = event => {
    if (event.key === 'ContextMenu' || (event.shiftKey && event.key === 'F10')) {
      event.preventDefault(); const rect = target.getBoundingClientRect(); openAt(rect.left + rect.width / 2, rect.top + rect.height / 2, true);
    }
  };
  const onMenuKey = event => {
    const enabled = enabledItems();
    let index = enabled.indexOf(document.activeElement);
    if (event.key === 'Escape') { event.preventDefault(); close(true); }
    else if (event.key === 'ArrowDown' || event.key === 'ArrowUp' || event.key === 'Home' || event.key === 'End') {
      event.preventDefault();
      index = event.key === 'Home' ? 0 : event.key === 'End' ? enabled.length - 1 : (index + (event.key === 'ArrowDown' ? 1 : -1) + enabled.length) % enabled.length;
      enabled[index]?.focus();
    }
  };
  const onAction = event => {
    const item = event.currentTarget;
    if (!(item instanceof HTMLButtonElement) || item.getAttribute('aria-disabled') === 'true') return;
    feedback.textContent = `${item.dataset.action} selected for Q3 launch plan.`;
    close(true);
  };
  const onOutside = event => { if (!menu.hidden && !root.contains(event.target)) close(); };
  target.addEventListener('contextmenu', onContext);
  visibleTrigger.addEventListener('click', onVisibleOpen);
  target.addEventListener('keydown', onTargetKey);
  menu.addEventListener('keydown', onMenuKey);
  items.forEach(item => item.addEventListener('click', onAction));
  document.addEventListener('pointerdown', onOutside);
  return { destroy() { target.removeEventListener('contextmenu', onContext); visibleTrigger.removeEventListener('click', onVisibleOpen); target.removeEventListener('keydown', onTargetKey); menu.removeEventListener('keydown', onMenuKey); items.forEach(item => item.removeEventListener('click', onAction)); document.removeEventListener('pointerdown', onOutside); } };
}
