export function createTieredMenu(root){
 const branches=[...root.querySelectorAll('[data-branch]')],output=root.querySelector('[data-menu-output]');
 const close=()=>branches.forEach(button=>{button.setAttribute('aria-expanded','false');button.nextElementSibling.hidden=true;});
 const open=button=>{close();button.setAttribute('aria-expanded','true');button.nextElementSibling.hidden=false;};
 const onClick=event=>{const button=event.target.closest('button');if(!button||!root.contains(button))return;if(button.hasAttribute('data-branch')){const active=button.getAttribute('aria-expanded')==='true';active?close():open(button);return;}if(button.hasAttribute('data-leaf')){output.textContent=`Selected: ${button.dataset.leaf}`;close();}};
 const onKey=event=>{const item=event.target.closest('[role="menuitem"]');if(!item||!root.contains(item))return;const menu=item.closest('[role="menu"]');const items=[...menu.querySelectorAll(':scope > button, :scope > .tiered-branch > button')];let index=items.indexOf(item);if(event.key==='ArrowDown'||event.key==='ArrowUp'){event.preventDefault();items[(index+(event.key==='ArrowDown'?1:-1)+items.length)%items.length].focus();}else if(event.key==='ArrowRight'&&item.hasAttribute('data-branch')){event.preventDefault();open(item);item.nextElementSibling.querySelector('button').focus();}else if(event.key==='ArrowLeft'&&menu.classList.contains('tiered-submenu')){event.preventDefault();const parent=menu.previousElementSibling;close();parent.focus();}else if(event.key==='Escape'){event.preventDefault();const parent=menu.classList.contains('tiered-submenu')?menu.previousElementSibling:null;close();parent?.focus();}};
 const onOutside=event=>{if(!root.contains(event.target))close();};root.addEventListener('click',onClick);root.addEventListener('keydown',onKey);document.addEventListener('pointerdown',onOutside);return{destroy(){root.removeEventListener('click',onClick);root.removeEventListener('keydown',onKey);document.removeEventListener('pointerdown',onOutside)}};
}
