  const add=(severity,title,detail,life=5000)=>{const toast=document.createElement('div');toast.className='toast-message';toast.dataset.severity=severity;toast.dataset.id=String(++nextId);toast.setAttribute('role',severity==='error'?'alert':'status');const icon=document.createElement('span');icon.className='toast-icon';icon.setAttribute('aria-hidden','true');icon.textContent=({success:'✓',info:'i',warn:'!',error:'×',loading:'…'})[severity]||'i';const body=document.createElement('div');body.className='toast-content';const heading=document.createElement('strong');heading.textContent=title;const copy=document.createElement('p');copy.textContent=detail;body.append(heading,copy);const close=document.createElement('button');close.className='toast-close';close.type='button';close.setAttribute('aria-label',`Dismiss ${title}`);close.textContent='×';toast.append(icon,body,close);stack.append(toast);stack.scrollTop=stack.scrollHeight;if(life)timers.set(toast,setTimeout(()=>remove(toast),life));return toast;};
  const remove=toast=>{clearTimeout(timers.get(toast));timers.delete(toast);toast.remove();};
