.c-carousel-demo {
  --carousel-accent: #b9f474; --carousel-border: #dcddd4; --carousel-canvas: #f5f5ef; --carousel-focus: #648f32; --carousel-muted: #62665d; --carousel-surface: #fff; --carousel-text: #171915;
  align-content: center; background: var(--carousel-canvas); color: var(--carousel-text); display: grid; font-family: Inter, ui-sans-serif, system-ui, sans-serif; min-height: 100%; padding: 2rem;
}
.c-carousel { background: var(--carousel-surface); border: 1px solid var(--carousel-border); border-radius: 1rem; inline-size: min(100%, 48rem); margin-inline: auto; overflow: hidden; }
.c-carousel__slide { display: grid; grid-template-columns: minmax(12rem, .9fr) minmax(0, 1.1fr); min-block-size: 17rem; }
.c-carousel__slide[hidden] { display: none; }
.c-carousel__art { align-items: center; display: flex; min-block-size: 12rem; overflow: hidden; padding: 1.5rem; }
.c-carousel__art span { color: rgb(23 25 21 / 62%); font-size: clamp(4rem, 10vw, 7rem); font-weight: 750; letter-spacing: -.1em; }
.c-carousel__art--one { background: linear-gradient(145deg, #dff4c9 0%, #b9d88f 48%, #f1f3e8 100%); }
.c-carousel__art--two { background: linear-gradient(145deg, #dcebed 0%, #a7c8cb 48%, #eff2ed 100%); }
.c-carousel__art--three { background: linear-gradient(145deg, #f2e4c9 0%, #d9bd91 48%, #f4efe4 100%); }
.c-carousel__copy { align-content: center; display: grid; gap: .8rem; padding: clamp(1.25rem, 4vw, 2.25rem); }
.c-carousel__eyebrow { color: var(--carousel-muted); font-size: .7rem; font-weight: 650; letter-spacing: .08em; margin: 0; text-transform: uppercase; }
.c-carousel__copy h2 { font-size: clamp(1.4rem, 4vw, 2.15rem); letter-spacing: -.05em; line-height: 1.05; margin: 0; }
.c-carousel__copy > p:last-child { color: var(--carousel-muted); line-height: 1.6; margin: 0; }
.c-carousel__controls { align-items: center; border-block-start: 1px solid var(--carousel-border); display: flex; gap: .8rem; justify-content: center; padding: .7rem 1rem; }
.c-carousel__arrow { align-items: center; background: transparent; border: 1px solid var(--carousel-border); border-radius: 50%; color: var(--carousel-text); cursor: pointer; display: inline-flex; font-size: 1.15rem; height: 2.5rem; justify-content: center; width: 2.5rem; }
