.c-carousel__indicators button[aria-current="true"] { background: var(--carousel-text); width: 1.35rem; }
.c-carousel__status { color: var(--carousel-muted); font-size: .72rem; margin: 0; padding: 0 1rem .8rem; text-align: center; }
