export function createCarousel(root) {
  const carousel = root.querySelector('[data-carousel]');
  const slides = [...(carousel?.querySelectorAll('[data-slide]') ?? [])];
  const previous = carousel?.querySelector('[data-previous]');
  const next = carousel?.querySelector('[data-next]');
  const status = carousel?.querySelector('[data-status]');
  const indicators = [...(carousel?.querySelectorAll('[data-indicator]') ?? [])];
  if (!carousel || slides.length < 2 || !previous || !next || !status) throw new Error('Carousel markup is incomplete.');
  let index = 0;
  const render = () => {
    slides.forEach((slide, slideIndex) => { slide.hidden = slideIndex !== index; });
    indicators.forEach((button, buttonIndex) => {
      if (buttonIndex === index) button.setAttribute('aria-current', 'true');
      else button.removeAttribute('aria-current');
    });
    status.textContent = `Slide ${index + 1} of ${slides.length}`;
  };
  const show = (nextIndex) => { index = (nextIndex + slides.length) % slides.length; render(); };
  const onPrevious = () => show(index - 1);
  const onNext = () => show(index + 1);
  const onKeydown = (event) => {
    if (event.key === 'ArrowLeft') { event.preventDefault(); onPrevious(); }
    if (event.key === 'ArrowRight') { event.preventDefault(); onNext(); }
  };
  const onIndicator = (event) => {
    const button = event.target.closest('[data-indicator]');
    if (button && carousel.contains(button)) show(Number(button.dataset.indicator));
  };
  previous.addEventListener('click', onPrevious);
  next.addEventListener('click', onNext);
  carousel.addEventListener('keydown', onKeydown);
  carousel.addEventListener('click', onIndicator);
  render();
  return { destroy() {
    previous.removeEventListener('click', onPrevious);
    next.removeEventListener('click', onNext);
    carousel.removeEventListener('keydown', onKeydown);
    carousel.removeEventListener('click', onIndicator);
  } };
}
document.querySelectorAll('[data-component="carousel"]').forEach(createCarousel);

