export function createMultiCarousel(root) {
  const carousel = root.querySelector('[data-multi-carousel]');
  const viewport = carousel?.querySelector('.c-multi__viewport');
  const track = carousel?.querySelector('[data-track]');
  const slides = [...(track?.children ?? [])];
  const previous = carousel?.querySelector('[data-previous]');
  const next = carousel?.querySelector('[data-next]');
  const status = carousel?.querySelector('[data-status]');
  const indicators = carousel?.querySelector('[data-indicators]');
  if (!carousel || !viewport || !track || slides.length < 2 || !previous || !next || !status || !indicators) throw new Error('Multi-item carousel markup is incomplete.');
  let index = 0;
  let visible = 1;
  const measure = () => {
    const width = viewport.clientWidth;
    visible = width >= 864 ? 3 : width >= 576 ? 2 : 1;
    slides.forEach((slide, slideIndex) => {
      slide.style.flexBasis = `${width / visible}px`;
      slide.setAttribute('aria-label', `${slideIndex + 1} of ${slides.length}`);
    });
    index = Math.min(index, Math.max(0, slides.length - visible));
    render();
  };
  const render = () => {
    const maxIndex = Math.max(0, slides.length - visible);
    track.style.transform = `translateX(-${index * (viewport.clientWidth / visible)}px)`;
    previous.disabled = index === 0;
    next.disabled = index >= maxIndex;
    const end = Math.min(index + visible, slides.length);
    status.textContent = `Items ${index + 1}–${end} of ${slides.length}`;
    indicators.replaceChildren();
    for (let page = 0; page <= maxIndex; page += 1) {
      const button = document.createElement('button');
      button.type = 'button';
      button.setAttribute('aria-label', `Show items starting at ${page + 1}`);
      if (page === index) button.setAttribute('aria-current', 'true');
      button.addEventListener('click', () => { index = page; render(); });
      indicators.append(button);
    }
  };
  const onPrevious = () => { index = Math.max(0, index - 1); render(); };
  const onNext = () => { index = Math.min(slides.length - visible, index + 1); render(); };
  const onKeydown = (event) => {
    if (event.key === 'ArrowLeft') { event.preventDefault(); onPrevious(); }
    if (event.key === 'ArrowRight') { event.preventDefault(); onNext(); }
  };
  carousel.addEventListener('keydown', onKeydown);
  previous.addEventListener('click', onPrevious);
  next.addEventListener('click', onNext);
  const observer = new ResizeObserver(measure);
  observer.observe(viewport);
  measure();
  return { destroy() { carousel.removeEventListener('keydown', onKeydown); previous.removeEventListener('click', onPrevious); next.removeEventListener('click', onNext); observer.disconnect(); } };
}
document.querySelectorAll('[data-component="multi-carousel"]').forEach(createMultiCarousel);

