export function createRotatingCarousel(root) {
  const carousel = root.querySelector('[data-rotating-carousel]');
  const slides = [...(carousel?.querySelectorAll('[data-slide]') ?? [])];
  const previous = carousel?.querySelector('[data-previous]');
  const next = carousel?.querySelector('[data-next]');
  const toggle = carousel?.querySelector('[data-rotation-toggle]');
  const status = carousel?.querySelector('[data-status]');
  const motionPreference = window.matchMedia('(prefers-reduced-motion: reduce)');
  if (!carousel || slides.length < 2 || !previous || !next || !toggle || !status) throw new Error('Rotating carousel markup is incomplete.');
  let index = 0;
  let timer;
  let running = false;
  let pointerPaused = false;
  let focusPaused = false;
  const render = () => {
    slides.forEach((slide, slideIndex) => { slide.hidden = slideIndex !== index; });
    status.setAttribute('aria-live', running ? 'off' : 'polite');
    status.textContent = `Story ${index + 1} of ${slides.length}`;
  };
  const show = (nextIndex) => { index = (nextIndex + slides.length) % slides.length; render(); };
  const schedule = () => {
    window.clearInterval(timer);
    timer = undefined;
    if (running && !pointerPaused && !focusPaused && !document.hidden && !motionPreference.matches) {
      timer = window.setInterval(() => show(index + 1), 5000);
    }
  };
  const stop = () => {
    running = false;
    schedule();
    toggle.setAttribute('aria-pressed', 'false');
    toggle.textContent = motionPreference.matches ? 'Rotation off (reduced motion)' : 'Start rotation';
    toggle.disabled = motionPreference.matches;
    status.setAttribute('aria-live', 'polite');
  };
  const start = () => {
    if (motionPreference.matches) return;
    running = true;
    toggle.textContent = 'Pause rotation';
    toggle.setAttribute('aria-pressed', 'true');
    status.setAttribute('aria-live', 'off');
    schedule();
  };
  const onToggle = () => running ? stop() : start();
  const onPrevious = () => { show(index - 1); schedule(); };
  const onNext = () => { show(index + 1); schedule(); };
  const onPointerEnter = () => { pointerPaused = true; schedule(); };
  const onPointerLeave = () => { pointerPaused = false; schedule(); };
  const onFocusIn = () => { focusPaused = true; schedule(); };
  const onFocusOut = (event) => { if (!carousel.contains(event.relatedTarget)) { focusPaused = false; schedule(); } };
  const onVisibility = () => schedule();
  const onMotionChange = () => { if (motionPreference.matches) stop(); else { toggle.disabled = false; toggle.textContent = 'Start rotation'; } };
  previous.addEventListener('click', onPrevious);
  next.addEventListener('click', onNext);
  toggle.addEventListener('click', onToggle);
  carousel.addEventListener('pointerenter', onPointerEnter);
  carousel.addEventListener('pointerleave', onPointerLeave);
  carousel.addEventListener('focusin', onFocusIn);
  carousel.addEventListener('focusout', onFocusOut);
  document.addEventListener('visibilitychange', onVisibility);
  motionPreference.addEventListener('change', onMotionChange);
  if (motionPreference.matches) stop();
  render();
  return { destroy() {
    stop(); previous.removeEventListener('click', onPrevious); next.removeEventListener('click', onNext); toggle.removeEventListener('click', onToggle);
    carousel.removeEventListener('pointerenter', onPointerEnter); carousel.removeEventListener('pointerleave', onPointerLeave);
    carousel.removeEventListener('focusin', onFocusIn); carousel.removeEventListener('focusout', onFocusOut);
    document.removeEventListener('visibilitychange', onVisibility); motionPreference.removeEventListener('change', onMotionChange);
  } };
}
document.querySelectorAll('[data-component="rotating-carousel"]').forEach(createRotatingCarousel);

