export function createAnimateOnScroll(root) {
  const viewport = root.querySelector('[data-scroll-viewport]');
  const items = [...root.querySelectorAll('[data-scroll-item]')];

  if (!(viewport instanceof HTMLElement) || !items.length) {
    throw new Error('Animate-on-scroll markup is incomplete.');
  }

  if (!('IntersectionObserver' in window)) {
    items.forEach((item) => item.classList.add('is-visible'));
    return { destroy() {} };
  }

  const observer = new IntersectionObserver((entries) => {
    entries.forEach((entry) => {
      entry.target.classList.toggle('is-visible', entry.isIntersecting);
    });
  }, {
    root: viewport,
    threshold: 0.18
  });

  items.forEach((item) => observer.observe(item));
  return {
    destroy() {
      observer.disconnect();
    }
  };
}

document.querySelectorAll('[data-component="animate-on-scroll"]').forEach(createAnimateOnScroll);

export function createTerminal(root){
  const form=root.querySelector('[data-form]'),input=root.querySelector('[data-input]'),history=root.querySelector('[data-history]');
  const commands={help:'Commands: help, status, date, clear, echo <text>',status:'All systems ready.',date:()=>new Date().toLocaleString()};
  const add=(text,kind='response')=>{const line=document.createElement('p');line.className=`terminal-${kind}`;line.textContent=text;history.append(line);history.scrollTop=history.scrollHeight;};
  const onSubmit=event=>{event.preventDefault();const value=input.value.trim();if(!value)return;add(`$ ${value}`,'prompt');input.value='';const [name,...args]=value.split(/\s+/);if(name==='clear'){history.replaceChildren();return;}if(name==='echo'){add(args.join(' '));return;}const command=commands[name.toLowerCase()];add(command?typeof command==='function'?command():command:`Unknown command: ${name}. Type help for options.`,command?'response':'error');};
  form.addEventListener('submit',onSubmit);return{destroy(){form.removeEventListener('submit',onSubmit)}};
}
document.querySelectorAll('[data-terminal]').forEach(createTerminal);
